// Stands in for a pull_manual_data.php response's records array.
// Deliberately awkward content per record: embedded single quotes
// (SQL-escaping risk), double quotes, a '--' sequence (SQL-comment
// risk if anything ever built a query without parameterization), a
// newline, and non-ASCII text (em-dash) -- exactly the kind of thing
// that's easy to get right for a normal string and wrong for one with
// a stray quote in it.
const records = [
    { record_type: 'incident', id: 101, category: 'anxiety', occurred_at: '2026-08-01 09:00:00',
      trigger_context: "Didn't sleep well -- woke at 3am", free_notes: 'Quote test: she said "call the doctor"' },
    { record_type: 'daily_log', id: 202, log_date: '2026-08-01', weight: 181.4, caffeine_servings: 2, alcohol_drinks: 0,
      free_notes: 'Line one\nLine two' },
    { record_type: 'therapy_session', id: 303, session_date: '2026-08-01', session_type: 'individual',
      summary: "Discussed Ward's progress -- good week" },
    { record_type: 'medication', id: 404, name: "Ward's test med (100mg)", start_date: '2026-01-01', dosage: '100mg' },
    { record_type: 'medication_dosage_history', id: 505, medication_name: 'Test Med', changed_at: '2026-08-01',
      old_dosage: '50mg', new_dosage: '100mg', notes: 'Dose doubled -- discussed with doctor' },
    // Out-of-scope on purpose -- must NOT appear in the backup table.
    { record_type: 'ecg_recording', id: 606, recorded_at: '2026-08-01 10:00:00', device_product: 'KardiaMobile' },
    { record_type: 'some_future_type', id: 707, whatever: 'should be ignored' },
    // Duplicate source_id for an in-scope type -- simulates re-backing-up
    // the same GoDaddy row twice; INSERT OR REPLACE should collapse this
    // to one row, not two, in the final count.
    { record_type: 'incident', id: 101, category: 'anxiety', occurred_at: '2026-08-01 09:00:00',
      trigger_context: 'UPDATED on second pass', free_notes: null }
];
msg.fixture_records = records;
return msg;

// Verbatim copy of the row-building half of godaddy_backup_flow.json's
// n_gb_process — deliberately duplicated so this test actually exercises
// what the real flow runs, not a paraphrase of it. If that node's logic
// ever changes, this needs updating too (same maintenance cost every
// other companion test flow in this project already accepts).
const inScope = { incident: true, daily_log: true, therapy_session: true, medication: true, medication_dosage_history: true };
function escSql(s) { return "'" + String(s).replace(/'/g, "''") + "'"; }
const now = new Date().toISOString();
const rows = [];
msg.fixture_records.forEach(r => {
    if (!inScope[r.record_type]) return;
    const sourceId = String((r.id !== undefined && r.id !== null) ? r.id : (Date.now() + '_' + Math.random()));
    rows.push('(' + escSql(r.record_type) + ',' + escSql(sourceId) + ',' + escSql(JSON.stringify(r)) + ',' + escSql(now) + ')');
});
msg.sqlite_row_count = rows.length;
msg.sqlite_insert_sql = rows.length
    ? 'INSERT OR REPLACE INTO godaddy_backup_test (record_type, source_id, data_json, backed_up_at) VALUES ' + rows.join(',')
    : null;
node.warn('Built ' + rows.length + ' SQL row(s) from ' + msg.fixture_records.length + ' fixture record(s) (2 out-of-scope filtered; expect these ' + rows.length + ' tuples to collapse to 5 distinct rows once INSERT OR REPLACE resolves the duplicate incident id).');
return msg;

msg.topic = "CREATE TABLE IF NOT EXISTS godaddy_backup_test (" +
    "record_type TEXT NOT NULL, source_id TEXT NOT NULL, data_json TEXT NOT NULL, " +
    "backed_up_at TEXT NOT NULL, PRIMARY KEY (record_type, source_id))";
return msg;

const rows = Array.isArray(msg.payload) ? msg.payload : [];
const problems = [];
const results = [];

function check(label, cond) { results.push((cond ? 'PASS' : 'FAIL') + ' — ' + label); if (!cond) problems.push(label); }

check('exactly 5 rows written (5 in-scope types; ecg_recording + unknown type filtered; duplicate incident id collapsed)', rows.length === 5);

const byKey = {};
rows.forEach(r => { byKey[r.record_type + ':' + r.source_id] = r; });

check('ecg_recording row absent', !byKey['ecg_recording:606']);
check('some_future_type row absent', !byKey['some_future_type:707']);

const incRow = byKey['incident:101'];
check('incident row present', !!incRow);
if (incRow) {
    let parsed;
    try { parsed = JSON.parse(incRow.data_json); } catch (e) { parsed = null; }
    check('incident JSON parses back', !!parsed);
    check('duplicate source_id collapsed to the SECOND write (INSERT OR REPLACE, not two rows)', parsed && parsed.trigger_context === 'UPDATED on second pass');
    check('null field survives round-trip as null', parsed && parsed.free_notes === null);
}

const dailyRow = byKey['daily_log:202'];
if (dailyRow) {
    const parsed = JSON.parse(dailyRow.data_json);
    check('daily_log embedded newline survives exactly', parsed.free_notes === 'Line one\nLine two');
    check('daily_log numeric fields survive as numbers, not strings', typeof parsed.weight === 'number' && parsed.weight === 181.4);
}

const therapyRow = byKey['therapy_session:303'];
if (therapyRow) {
    const parsed = JSON.parse(therapyRow.data_json);
    check('therapy_session embedded single quote + double-dash survives', parsed.summary === "Discussed Ward's progress -- good week");
}

const medRow = byKey['medication:404'];
if (medRow) {
    const parsed = JSON.parse(medRow.data_json);
    check('medication name with apostrophe survives', parsed.name === "Ward's test med (100mg)");
}

const doseRow = byKey['medication_dosage_history:505'];
if (doseRow) {
    const parsed = JSON.parse(doseRow.data_json);
    check('medication_dosage_history notes with double-dash survives', parsed.notes === 'Dose doubled -- discussed with doctor');
}

msg.test_results = results;
msg.test_problems = problems;
msg.topic = 'DROP TABLE IF EXISTS godaddy_backup_test';
return msg;

const problems = msg.test_problems || [];
const summary = (problems.length ? ('❌ ' + problems.length + ' PROBLEM(S) FOUND') : '✅ ALL CHECKS PASSED') ;
node.status({ fill: problems.length ? 'red' : 'green', shape: 'dot', text: summary });
msg.payload = {
    summary: summary,
    results: msg.test_results,
    problems: problems,
};
return msg;
